import { _decorator, Component, director, Label, Node, Tween, tween, UIOpacity, Vec3 } from 'cc';
import { sp } from 'cc';
import AppAudio from '../audio/AppAudio';
import { EFFECTSMAP } from '../audio/AudioConfig';
import StoreManager from '../store/StoreManager';
import { GameViewAdapter } from './GameViewAdapter';

const { ccclass, property } = _decorator;

// const JP_ANIM_PREFIX: Record<string, string> = {
//     mini: '01_MINI/MINI',
//     minor: '02_MINOR/MINOR',
//     major: '03_MAJOR/MAJOR',
//     grand: '04_GRAND/GRAND',
// };

const JP_TIERS = ['mini', 'minor', 'major', 'grand'] as const;

const CLOSE_BUMP_SCALE = 1.2; // 縮放
const CLOSE_BUMP_DURATION = 0.133; // 放大的時間
const CLOSE_SHRINK_DURATION = 0.2; // 縮小的時間
const JACKPOT_AUTO_DISMISS_SEC = 5; // 安全閥：5 秒後強制關閉

@ccclass('1001/JackpotView')
export class JackpotView extends Component {
    @property(Label)
    winAmountLabel: Label = null!;

    @property(sp.Skeleton)
    bgSpine: sp.Skeleton = null!;

    private resolveClick: (() => void) | null = null;
    private dismissTimer: (() => void) | null = null;
    private dismissed: boolean = false;
    private bgSpineOriginalScale: Vec3 = new Vec3(1, 1, 1);

    /** dismiss 的瞬間觸發（給 peer view 同步用） */
    public onDismissing: (() => void) | null = null;

    protected override onLoad(): void {
        this.node.on(Node.EventType.TOUCH_END, this.onTouchEnd, this);
        this.bgSpineOriginalScale.set(this.bgSpine.node.scale);
        this.applyAdapterOverride();
        this.bgSpine.node.setScale(this.bgSpineOriginalScale);
        // 1001 現行入口：GamePopupManager.showJackpotOnAll()
    }

    /** 直版跟橫版縮放 抓prefab 初始 scale */
    private applyAdapterOverride(): void {
        const isPortrait = StoreManager.getInstance().getDeviceStore().isPortrait;
        const adapterName = isPortrait ? 'GameViewV' : 'GameViewH';
        const scene = director.getScene();
        if (!scene) return;
        const adapter = scene.getComponentsInChildren(GameViewAdapter).find((a) => a.node.name === adapterName);
        if (!adapter) return;
        const lp = adapter.jackpotBgSpineLpos;
        if (lp && (lp.x !== 0 || lp.y !== 0 || lp.z !== 0)) this.bgSpine.node.setPosition(lp);
        const sc = adapter.jackpotBgSpineScale;
        if (sc && (sc.x !== 0 || sc.y !== 0 || sc.z !== 0)) {
            this.bgSpineOriginalScale = new Vec3(
                this.bgSpineOriginalScale.x * sc.x,
                this.bgSpineOriginalScale.y * sc.y,
                this.bgSpineOriginalScale.z * sc.z
            );
        }
    }

    /**
     * 顯示 JP 中獎彈窗
     * @param jpType 'mini' | 'minor' | 'major' | 'grand'
     * @param amount 中獎金額
     */
    show(jpType: string, amount: number): Promise<void> {
        // const prefix = JP_ANIM_PREFIX[jpType];
        // if (!prefix) return Promise.resolve();

        if (!(JP_TIERS as readonly string[]).includes(jpType)) return Promise.resolve();

        Tween.stopAllByTarget(this.bgSpine.node);
        this.bgSpine.node.setScale(this.bgSpineOriginalScale);

        this.node.active = true;
        this.dismissed = false;
        this.winAmountLabel.string = StoreManager.getInstance().getGameStore().formatAmount(amount);

        AppAudio.getInstance().playEffect(EFFECTSMAP.GETJACKPOT);

        this.playLabelOpen(this.winAmountLabel);

        // 播 open → loop（播一次）→ 自動關
        try {
            this.bgSpine.setAnimation(0, `${jpType}_begin`, false);
            this.bgSpine.setCompleteListener(() => {
                this.bgSpine.setCompleteListener(null!);
                this.bgSpine.setAnimation(0, `${jpType}_loop`, true);
                // this.playLabelIdle(this.winAmountLabel);
            });
        } catch (e) {
            // 動畫播放失敗，直接關閉
            this.dismiss();
        }
        const dismissCb = () => this.dismiss();
        this.dismissTimer = dismissCb;
        this.scheduleOnce(dismissCb, JACKPOT_AUTO_DISMISS_SEC);
        return new Promise<void>((resolve) => {
            this.resolveClick = resolve;
        });
    }

    // private currentPrefix: string = '';

    /** 給外部呼叫的 dismiss（peer view 同步用） */
    public dismissExternal(): void {
        this.dismiss();
    }

    private _notifying: boolean = false;
    private dismiss(): void {
        if (this.dismissed) return;
        this.dismissed = true;
        // 通知 peer view 同步開始 dismiss（在播 close 動畫之前）// 沒有close了喔
        if (!this._notifying) {
            this._notifying = true;
            try {
                this.onDismissing?.();
            } finally {
                this._notifying = false;
            }
        }
        if (this.dismissTimer) {
            this.unschedule(this.dismissTimer);
            this.dismissTimer = null;
        }

        // win_jp 只有 begin/loop
        this.bgSpine.setCompleteListener(null!);
        this.playLabelClose(this.winAmountLabel);

        // 從當前 loop 動畫名稱推回 prefix
        // const currentAnim = this.bgSpine.animation;
        // let prefix = '';
        // for (const [, p] of Object.entries(JP_ANIM_PREFIX)) {
        //     if (currentAnim?.includes(p)) {
        //         prefix = p;
        //         break;
        //     }
        // }
        // if (!prefix) {
        //     this.close();
        //     return;
        // }

        // // 播 close 動畫後隱藏
        // try {
        //     this.bgSpine.setAnimation(0, `${prefix}_close`, false);
        //     const safetyTimer = setTimeout(() => this.close(), 1000);
        //     this.bgSpine.setCompleteListener(() => {
        //         clearTimeout(safetyTimer);
        //         this.bgSpine.setCompleteListener(null!);
        //         this.close();
        //     });
        // } catch (e) {
        //     this.close();
        // }

        const originalScale = this.bgSpineOriginalScale;

        Tween.stopAllByTarget(this.bgSpine.node);
        tween(this.bgSpine.node)
            .to(CLOSE_BUMP_DURATION, {
                scale: new Vec3(originalScale.x * CLOSE_BUMP_SCALE, originalScale.y * CLOSE_BUMP_SCALE, originalScale.z)
            })
            .to(
                CLOSE_SHRINK_DURATION,
                {
                    scale: new Vec3(0, 0, originalScale.z)
                },
                { easing: 'backIn' }
            )
            .call(() => this.close())
            .start();
    }

    /** open: delay 0.167s → 0→1.2(0.167s) → 1.2→0.9(0.167s) → 0.9→1.0(0.167s) 比照 win_jp 的 board */
    private playLabelOpen(label: Label): void {
        const node = label.node;
        Tween.stopAllByTarget(node);
        node.setScale(0, 0, 1);

        // board 全程不透明 淡入會蓋掉整段放大過程
        const uiOpacity = node.getComponent(UIOpacity) || node.addComponent(UIOpacity);
        Tween.stopAllByTarget(uiOpacity);
        uiOpacity.opacity = 255;

        tween(node)
            .delay(0.167)
            .to(0.167, { scale: new Vec3(1.2, 1.2, 1) }, { easing: 'smooth' })
            .to(0.167, { scale: new Vec3(0.9, 0.9, 1) }, { easing: 'smooth' })
            .to(0.167, { scale: new Vec3(1, 1, 1) }, { easing: 'smooth' })
            .start();
    }

    /** idle: 1.0→1.1(0.167s)→1.0(0.133s)→1.3(0.267s)→1.0(0.433s) 雙波呼吸循環 */
    private playLabelIdle(label: Label): void {
        const node = label.node;
        Tween.stopAllByTarget(node);
        tween(node)
            .to(0.167, { scale: new Vec3(1.1, 1.1, 1) })
            .to(0.133, { scale: new Vec3(1, 1, 1) })
            .to(0.267, { scale: new Vec3(1.3, 1.3, 1) })
            .to(0.433, { scale: new Vec3(1, 1, 1) })
            .union()
            .repeatForever()
            .start();
    }

    private playLabelClose(label: Label): void {
        const node = label.node;
        Tween.stopAllByTarget(node);

        const uiOpacity = node.getComponent(UIOpacity) || node.addComponent(UIOpacity);
        uiOpacity.opacity = 255;
        tween(uiOpacity).delay(CLOSE_BUMP_DURATION).to(CLOSE_SHRINK_DURATION, { opacity: 0 }).start();

        tween(node)
            .to(CLOSE_BUMP_DURATION, { scale: new Vec3(CLOSE_BUMP_SCALE, CLOSE_BUMP_SCALE, 1) })
            .to(CLOSE_SHRINK_DURATION, { scale: new Vec3(0, 0, 1) })
            .start();
    }

    private close(): void {
        if (this.node?.isValid) {
            this.node.active = false;
            this.bgSpine.node.setScale(this.bgSpineOriginalScale);
        }
        this.resolveClick?.();
        this.resolveClick = null;
    }

    private onTouchEnd(): void {
        this.dismiss();
    }

    protected override onDestroy(): void {
        this.node.off(Node.EventType.TOUCH_END, this.onTouchEnd, this);
        Tween.stopAllByTarget(this.bgSpine.node);
        if (this.dismissTimer) {
            this.unschedule(this.dismissTimer);
            this.dismissTimer = null;
        }
    }
}
